299	  private void runWrapped() {
300	    switch (runReason) {
301	      case INITIALIZE:
302	        stage = getNextStage(Stage.INITIALIZE);
303	        currentGenerator = getNextGenerator();
304	        runGenerators();
305	        break;
306	      case SWITCH_TO_SOURCE_SERVICE:
307	        runGenerators();
308	        break;
309	      case DECODE_DATA:
310	        decodeFromRetrievedData();
311	        break;
312	      default:
313	        throw new IllegalStateException("Unrecognized run reason: " + runReason);
314	    }
315	  }
316	
317	  private DataFetcherGenerator getNextGenerator() {
318	    switch (stage) {
319	      case RESOURCE_CACHE:
320	        return new ResourceCacheGenerator(decodeHelper, this);
321	      case DATA_CACHE:
322	        return new DataCacheGenerator(decodeHelper, this);
323	      case SOURCE:
324	        return new SourceGenerator(decodeHelper, this);
325	      case FINISHED:
326	        return null;
327	      default:
328	        throw new IllegalStateException("Unrecognized stage: " + stage);
329	    }
330	  }
331	
332	  private void runGenerators() {
333	    currentThread = Thread.currentThread();
334	    startFetchTime = LogTime.getLogTime();
335	    boolean isStarted = false;
336	    while (!isCancelled
337	        && currentGenerator != null
338	        && !(isStarted = currentGenerator.startNext())) {
339	      stage = getNextStage(stage);
340	      currentGenerator = getNextGenerator();
341	
342	      if (stage == Stage.SOURCE) {
343	        reschedule(RunReason.SWITCH_TO_SOURCE_SERVICE);
344	        return;
345	      }
346	    }
347	    // We've run out of stages and generators, give up.
348	    if ((stage == Stage.FINISHED || isCancelled) && !isStarted) {
349	      notifyFailed();
350	    }
351	
352	    // Otherwise a generator started a new load and we expect to be called back in
353	    // onDataFetcherReady.
354	  }
