440	  @Override
441	  public void onDataFetcherReady(
442	      Key sourceKey, Object data, DataFetcher<?> fetcher, DataSource dataSource, Key attemptedKey) {
443	    this.currentSourceKey = sourceKey;
444	    this.currentData = data;
445	    this.currentFetcher = fetcher;
446	    this.currentDataSource = dataSource;
447	    this.currentAttemptingKey = attemptedKey;
448	    this.isLoadingFromAlternateCacheKey = sourceKey != decodeHelper.getCacheKeys().get(0);
449	
450	    if (Thread.currentThread() != currentThread) {
451	      reschedule(RunReason.DECODE_DATA);
452	    } else {
453	      GlideTrace.beginSection("DecodeJob.decodeFromRetrievedData");
454	      try {
455	        decodeFromRetrievedData();
456	      } finally {
457	        GlideTrace.endSection();
458	      }
459	    }
460	  }
