476	  private void decodeFromRetrievedData() {
477	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
478	      logWithTimeAndKey(
479	          "Retrieved data",
480	          startFetchTime,
481	          "data: "
482	              + currentData
483	              + ", cache key: "
484	              + currentSourceKey
485	              + ", fetcher: "
486	              + currentFetcher);
487	    }
488	    if (experiments.isEnabled(OverrideGlideThreadPriority.class)
489	        && glideThreadPriorityOverride != null
490	        && glideThreadPriorityOverride.get() != null) {
491	      try {
492	        Process.setThreadPriority(Process.myTid(), glideThreadPriorityOverride.get().intValue());
493	      } catch (IllegalArgumentException | SecurityException e) {
494	        glideThreadPriorityOverride = null;
495	        if (Log.isLoggable(TAG, Log.VERBOSE)) {
496	          Log.v(
497	              TAG,
498	              "Failed to set thread priority; using default priority for any subsequent jobs.",
499	              e);
500	        }
501	      }
502	    }
503	    Resource<R> resource = null;
504	    try {
505	      resource = decodeFromData(currentFetcher, currentData, currentDataSource);
506	    } catch (GlideException e) {
507	      e.setLoggingDetails(currentAttemptingKey, currentDataSource);
508	      throwables.add(e);
509	    }
510	    if (resource != null) {
511	      notifyEncodeAndRelease(resource, currentDataSource, isLoadingFromAlternateCacheKey);
512	    } else {
513	      runGenerators();
514	    }
515	  }
516	
517	  private void notifyEncodeAndRelease(
518	      Resource<R> resource, DataSource dataSource, boolean isLoadedFromAlternateCacheKey) {
519	    GlideTrace.beginSection("DecodeJob.notifyEncodeAndRelease");
520	    try {
521	      if (resource instanceof Initializable) {
522	        ((Initializable) resource).initialize();
523	      }
524	
525	      Resource<R> result = resource;
526	      LockedResource<R> lockedResource = null;
527	      if (deferredEncodeManager.hasResourceToEncode()) {
528	        lockedResource = LockedResource.obtain(resource);
529	        result = lockedResource;
530	      }
531	
532	      notifyComplete(result, dataSource, isLoadedFromAlternateCacheKey);
533	
534	      stage = Stage.ENCODE;
535	      try {
536	        if (deferredEncodeManager.hasResourceToEncode()) {
537	          deferredEncodeManager.encode(diskCacheProvider, options);
538	        }
539	      } finally {
540	        if (lockedResource != null) {
541	          lockedResource.unlock();
542	        }
543	      }
544	      // Call onEncodeComplete outside the finally block so that it's not called if the encode
545	      // process
546	      // throws.
547	      onEncodeComplete();
548	    } finally {
549	      GlideTrace.endSection();
550	    }
551	  }
552	
553	  private <Data> Resource<R> decodeFromData(
554	      DataFetcher<?> fetcher, Data data, DataSource dataSource) throws GlideException {
555	    try {
556	      if (data == null) {
557	        return null;
558	      }
559	      long startTime = LogTime.getLogTime();
560	      Resource<R> result = decodeFromFetcher(data, dataSource);
561	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
562	        logWithTimeAndKey("Decoded result " + result, startTime);
563	      }
564	      return result;
565	    } finally {
566	      fetcher.cleanup();
567	    }
568	  }
569	
570	  @SuppressWarnings("unchecked")
571	  private <Data> Resource<R> decodeFromFetcher(Data data, DataSource dataSource)
572	      throws GlideException {
573	    LoadPath<Data, ?, R> path = decodeHelper.getLoadPath((Class<Data>) data.getClass());
574	    return runLoadPath(data, dataSource, path);
575	  }
576	
577	  @NonNull
578	  private Options getOptionsWithHardwareConfig(DataSource dataSource) {
579	    Options options = this.options;
580	    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
581	      return options;
582	    }
583	
584	    boolean isHardwareConfigSafe =
585	        dataSource == DataSource.RESOURCE_DISK_CACHE || decodeHelper.isScaleOnlyOrNoTransform();
586	    Boolean isHardwareConfigAllowed = options.get(Downsampler.ALLOW_HARDWARE_CONFIG);
587	
588	    // If allow hardware config is defined, we can use it if it's set to false or if it's safe to
589	    // use the hardware config for the request.
590	    if (isHardwareConfigAllowed != null && (!isHardwareConfigAllowed || isHardwareConfigSafe)) {
591	      return options;
592	    }
593	
594	    // If allow hardware config is undefined or is set to true but it's unsafe for us to use the
595	    // hardware config for this request, we need to override the config.
596	    options = new Options();
597	    options.putAll(this.options);
598	    options.set(Downsampler.ALLOW_HARDWARE_CONFIG, isHardwareConfigSafe);
599	
600	    return options;
601	  }
602	
603	  private <Data, ResourceType> Resource<R> runLoadPath(
604	      Data data, DataSource dataSource, LoadPath<Data, ResourceType, R> path)
605	      throws GlideException {
606	    Options options = getOptionsWithHardwareConfig(dataSource);
607	    DataRewinder<Data> rewinder = glideContext.getRegistry().getRewinder(data);
608	    try {
609	      // ResourceType in DecodeCallback below is required for compilation to work with gradle.
610	      return path.load(
611	          rewinder, options, width, height, new DecodeCallback<ResourceType>(dataSource));
612	    } finally {
613	      rewinder.cleanup();
614	    }
615	  }
