621	  private void logWithTimeAndKey(String message, long startTime, String extraArgs) {
622	    Log.v(
623	        TAG,
624	        message
625	            + " in "
626	            + LogTime.getElapsedMillis(startTime)
627	            + ", load key: "
628	            + loadKey
629	            + (extraArgs != null ? ", " + extraArgs : "")
630	            + ", thread: "
631	            + Thread.currentThread().getName());
632	  }
