640	  @Synthetic
641	  @NonNull
642	  <Z> Resource<Z> onResourceDecoded(DataSource dataSource, @NonNull Resource<Z> decoded) {
643	    @SuppressWarnings("unchecked")
644	    Class<Z> resourceSubClass = (Class<Z>) decoded.get().getClass();
645	    Transformation<Z> appliedTransformation = null;
646	    Resource<Z> transformed = decoded;
647	    if (dataSource != DataSource.RESOURCE_DISK_CACHE) {
648	      appliedTransformation = decodeHelper.getTransformation(resourceSubClass);
649	      if (shouldBypassSoftwareTransformation(decoded, appliedTransformation)) {
650	        if (Log.isLoggable(TAG, Log.VERBOSE)) {
651	          Log.v(
652	              TAG,
653	              "Bypassing software transformations for resource: "
654	                  + decoded.get()
655	                  + " with transformation: "
656	                  + appliedTransformation);
657	        }
658	      } else {
659	        transformed = appliedTransformation.transform(glideContext, decoded, width, height);
660	      }
661	    }
662	    // TODO: Make this the responsibility of the Transformation.
663	    if (!decoded.equals(transformed)) {
664	      decoded.recycle();
665	    }
666	
667	    final EncodeStrategy encodeStrategy;
668	    final ResourceEncoder<Z> encoder;
669	    if (decodeHelper.isResourceEncoderAvailable(transformed)) {
670	      encoder = decodeHelper.getResultEncoder(transformed);
671	      encodeStrategy = encoder.getEncodeStrategy(options);
672	    } else {
673	      encoder = null;
674	      encodeStrategy = EncodeStrategy.NONE;
675	    }
676	
677	    Resource<Z> result = transformed;
678	    boolean isFromAlternateCacheKey = !decodeHelper.isSourceKey(currentSourceKey);
679	    boolean isResourceCacheable =
680	        isResourceCacheable(isFromAlternateCacheKey, dataSource, encodeStrategy, transformed);
681	    if (isResourceCacheable) {
682	      if (encoder == null) {
683	        throw new Registry.NoResultEncoderAvailableException(transformed.get().getClass());
684	      }
685	      final Key key;
686	      switch (encodeStrategy) {
687	        case SOURCE:
688	          key = new DataCacheKey(currentSourceKey, signature);
689	          break;
690	        case TRANSFORMED:
691	          key =
692	              new ResourceCacheKey(
693	                  decodeHelper.getArrayPool(),
694	                  currentSourceKey,
695	                  signature,
696	                  width,
697	                  height,
698	                  appliedTransformation,
699	                  resourceSubClass,
700	                  options);
701	          break;
702	        default:
703	          throw new IllegalArgumentException("Unknown strategy: " + encodeStrategy);
704	      }
705	
706	      LockedResource<Z> lockedResult = LockedResource.obtain(transformed);
707	      deferredEncodeManager.init(key, encoder, lockedResult);
708	      result = lockedResult;
709	    }
710	    return result;
711	  }
