793	  /**
794	   * Responsible for indicating when it is safe for the job to be cleared and returned to the pool.
795	   */
796	  private static class ReleaseManager {
797	    private boolean isReleased;
798	    private boolean isEncodeComplete;
799	    private boolean isFailed;
800	
801	    @Synthetic
802	    ReleaseManager() {}
803	
804	    synchronized boolean release(boolean isRemovedFromQueue) {
805	      isReleased = true;
806	      return isComplete(isRemovedFromQueue);
807	    }
808	
809	    synchronized boolean onEncodeComplete() {
810	      isEncodeComplete = true;
811	      return isComplete(false /*isRemovedFromQueue*/);
812	    }
813	
814	    synchronized boolean onFailed() {
815	      isFailed = true;
816	      return isComplete(false /*isRemovedFromQueue*/);
817	    }
818	
819	    synchronized void reset() {
820	      isEncodeComplete = false;
821	      isReleased = false;
822	      isFailed = false;
823	    }
824	
825	    private boolean isComplete(boolean isRemovedFromQueue) {
826	      return (isFailed || isRemovedFromQueue || isEncodeComplete) && isReleased;
827	    }
828	  }
