830	  /**
831	   * Allows transformed resources to be encoded after the transcoded result is already delivered to
832	   * requestors.
833	   */
834	  private static class DeferredEncodeManager<Z> {
835	    private Key key;
836	    private ResourceEncoder<Z> encoder;
837	    private LockedResource<Z> toEncode;
838	
839	    @Synthetic
840	    DeferredEncodeManager() {}
841	
842	    // We just need the encoder and resource type to match, which this will enforce.
843	    @SuppressWarnings("unchecked")
844	    <X> void init(Key key, ResourceEncoder<X> encoder, LockedResource<X> toEncode) {
845	      this.key = key;
846	      this.encoder = (ResourceEncoder<Z>) encoder;
847	      this.toEncode = (LockedResource<Z>) toEncode;
848	    }
849	
850	    void encode(DiskCacheProvider diskCacheProvider, Options options) {
851	      GlideTrace.beginSection("DecodeJob.encode");
852	      try {
853	        diskCacheProvider
854	            .getDiskCache()
855	            .put(key, new DataCacheWriter<>(encoder, toEncode, options));
856	      } finally {
857	        toEncode.unlock();
858	        GlideTrace.endSection();
859	      }
860	    }
861	
862	    boolean hasResourceToEncode() {
863	      return toEncode != null;
864	    }
865	
866	    void clear() {
867	      key = null;
868	      encoder = null;
869	      toEncode = null;
870	    }
871	  }
