349	  /**
350	   * Logs memory cache hits (from active resources or memory cache). Handles both raw Bitmaps and
351	   * Bitmaps wrapped inside BitmapDrawable resources.
352	   */
353	  private static void logCacheHit(String source, EngineKey key, EngineResource<?> resource) {
354	    if (!Log.isLoggable(GLIDE_MEMORY_TRACKING_TAG, Log.DEBUG)) {
355	      return;
356	    }
357	
358	    Object data = resource.get();
359	    Bitmap bitmap = null;
360	    if (data instanceof Bitmap) {
361	      bitmap = (Bitmap) data;
362	    } else if (data instanceof android.graphics.drawable.BitmapDrawable) {
363	      bitmap = ((android.graphics.drawable.BitmapDrawable) data).getBitmap();
364	    }
365	    if (bitmap == null) {
366	      return;
367	    }
368	
369	    int bitmapIdentity = System.identityHashCode(bitmap);
370	    Log.d(
371	        GLIDE_MEMORY_TRACKING_TAG,
372	        "Engine [Device: "
373	            + android.os.Build.DEVICE
374	            + "]: Loaded bitmap [ID: "
375	            + bitmapIdentity
376	            + "] from memory cache ("
377	            + source
378	            + "). Size: ["
379	            + bitmap.getWidth()
380	            + "x"
381	            + bitmap.getHeight()
382	            + "] ("
383	            + Util.getBitmapByteSize(bitmap)
384	            + " bytes)");
385	  }
