6	import com.bumptech.glide.util.LruCache;
7	import com.bumptech.glide.util.Preconditions;
8	import com.bumptech.glide.util.Synthetic;
9	import com.bumptech.glide.util.Util;
10	import com.bumptech.glide.util.pool.FactoryPools;
11	import com.bumptech.glide.util.pool.StateVerifier;
12	import java.security.MessageDigest;
13	import java.security.NoSuchAlgorithmException;
14	
15	/**
16	 * A class that generates and caches safe and unique string file names from {@link
17	 * com.bumptech.glide.load.Key}s.
18	 */
19	// Public API.
20	@SuppressWarnings("WeakerAccess")
21	public class SafeKeyGenerator {
22	  private final LruCache<Key, String> loadIdToSafeHash = new LruCache<>(1000);
23	  private final Pools.Pool<PoolableDigestContainer> digestPool =
24	      FactoryPools.threadSafe(
25	          10,
26	          new FactoryPools.Factory<PoolableDigestContainer>() {
27	            @Override
28	            public PoolableDigestContainer create() {
29	              try {
30	                return new PoolableDigestContainer(MessageDigest.getInstance("SHA-256"));
31	              } catch (NoSuchAlgorithmException e) {
32	                throw new RuntimeException(e);
33	              }
34	            }
35	          });
36	
37	  public String getSafeKey(Key key) {
38	    String safeKey;
39	    synchronized (loadIdToSafeHash) {
40	      safeKey = loadIdToSafeHash.get(key);
41	    }
42	    if (safeKey == null) {
43	      safeKey = calculateHexStringDigest(key);
44	    }
45	    synchronized (loadIdToSafeHash) {
46	      loadIdToSafeHash.put(key, safeKey);
47	    }
48	    return safeKey;
49	  }
50	
51	  private String calculateHexStringDigest(Key key) {
52	    PoolableDigestContainer container = Preconditions.checkNotNull(digestPool.acquire());
53	    try {
54	      key.updateDiskCacheKey(container.messageDigest);
55	      // calling digest() will automatically reset()
56	      return Util.sha256BytesToHex(container.messageDigest.digest());
57	    } finally {
58	      digestPool.release(container);
59	    }
60	  }
61	
62	  private static final class PoolableDigestContainer implements FactoryPools.Poolable {
63	
64	    @Synthetic final MessageDigest messageDigest;
65	    private final StateVerifier stateVerifier = StateVerifier.newInstance();
66	
67	    PoolableDigestContainer(MessageDigest messageDigest) {
68	      this.messageDigest = messageDigest;
69	    }
70	
71	    @NonNull
72	    @Override
73	    public StateVerifier getVerifier() {
74	      return stateVerifier;
75	    }
76	  }
77	}
