513	    /**
514	     * Sets the {@link UncaughtThrowableStrategy} to use for unexpected exceptions thrown by tasks
515	     * on {@link GlideExecutor}s built by this {@code Builder}.
516	     */
517	    public Builder setUncaughtThrowableStrategy(@NonNull UncaughtThrowableStrategy strategy) {
518	      this.uncaughtThrowableStrategy = strategy;
519	      return this;
520	    }
521	
522	    /**
523	     * Sets the prefix to use for each thread name created by any {@link GlideExecutor}s built by
524	     * this {@code Builder}.
525	     */
526	    public Builder setName(String name) {
