540	    }
541	
542	    /** Builds a new {@link GlideExecutor} with any previously specified options. */
543	    public GlideExecutor build() {
544	      if (TextUtils.isEmpty(name)) {
545	        throw new IllegalArgumentException(
546	            "Name must be non-null and non-empty, but given: " + name);
547	      }
548	      ThreadFactory factory =
549	          new DefaultThreadFactory(
550	              threadFactory, name, uncaughtThrowableStrategy, preventNetworkOperations);
551	      BlockingQueue<Runnable> queue =
552	          isUnlimited ? new SynchronousQueue<>() : new PriorityBlockingQueue<>();
