2	
3	import android.graphics.Bitmap;
4	import android.os.Handler;
5	import android.os.Looper;
6	import android.os.SystemClock;
7	import android.util.Log;
8	import androidx.annotation.NonNull;
9	import androidx.annotation.VisibleForTesting;
10	import com.bumptech.glide.load.Key;
11	import com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool;
12	import com.bumptech.glide.load.engine.cache.MemoryCache;
13	import com.bumptech.glide.load.resource.bitmap.BitmapResource;
14	import com.bumptech.glide.util.Synthetic;
15	import com.bumptech.glide.util.Util;
16	import java.security.MessageDigest;
17	import java.util.HashSet;
18	import java.util.Set;
19	import java.util.concurrent.TimeUnit;
20	
21	/**
22	 * A class that allocates {@link android.graphics.Bitmap Bitmaps} to make sure that the {@link
23	 * com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool} is pre-populated.
24	 *
25	 * <p>By posting to the main thread with backoffs, we try to avoid ANRs when the garbage collector
26	 * gets into a state where a high percentage of {@link Bitmap} allocations trigger a stop the world
27	 * GC. We try to detect whether or not a GC has occurred by only allowing our allocator to run for a
28	 * limited number of milliseconds. Since the allocations themselves very fast, a GC is the most
29	 * likely reason for a substantial delay. If we detect our allocator has run for more than our
30	 * limit, we assume a GC has occurred, stop the current allocations, and try again after a delay.
31	 */
32	final class BitmapPreFillRunner implements Runnable {
33	  @VisibleForTesting static final String TAG = "PreFillRunner";
34	  private static final Clock DEFAULT_CLOCK = new Clock();
35	
36	  /**
37	   * The maximum number of millis we can run before posting. Set to match and detect the duration of
38	   * non concurrent GCs.
39	   */
40	  static final long MAX_DURATION_MS = 32;
41	
42	  /**
43	   * The amount of time in ms we wait before continuing to allocate after the first GC is detected.
44	   */
45	  static final long INITIAL_BACKOFF_MS = 40;
46	
47	  /** The amount by which the current backoff time is multiplied each time we detect a GC. */
48	  static final int BACKOFF_RATIO = 4;
49	
50	  /** The maximum amount of time in ms we wait before continuing to allocate. */
51	  static final long MAX_BACKOFF_MS = TimeUnit.SECONDS.toMillis(1);
52	
53	  private final BitmapPool bitmapPool;
54	  private final MemoryCache memoryCache;
55	  private final PreFillQueue toPrefill;
56	  private final Clock clock;
57	  private final Set<PreFillType> seenTypes = new HashSet<>();
58	  private final Handler handler;
59	
60	  private long currentDelay = INITIAL_BACKOFF_MS;
61	  private boolean isCancelled;
62	
63	  // Public API.
64	  @SuppressWarnings("WeakerAccess")
65	  public BitmapPreFillRunner(
66	      BitmapPool bitmapPool, MemoryCache memoryCache, PreFillQueue allocationOrder) {
67	    this(
68	        bitmapPool,
69	        memoryCache,
70	        allocationOrder,
71	        DEFAULT_CLOCK,
72	        new Handler(Looper.getMainLooper()));
73	  }
74	
75	  @VisibleForTesting
76	  BitmapPreFillRunner(
77	      BitmapPool bitmapPool,
78	      MemoryCache memoryCache,
79	      PreFillQueue allocationOrder,
80	      Clock clock,
81	      Handler handler) {
82	    this.bitmapPool = bitmapPool;
83	    this.memoryCache = memoryCache;
84	    this.toPrefill = allocationOrder;
85	    this.clock = clock;
86	    this.handler = handler;
87	  }
88	
89	  public void cancel() {
90	    isCancelled = true;
91	  }
92	
93	  /**
94	   * Attempts to allocate {@link android.graphics.Bitmap}s and returns {@code true} if there are
95	   * more {@link android.graphics.Bitmap}s to allocate and {@code false} otherwise.
96	   */
97	  @VisibleForTesting
98	  boolean allocate() {
99	    long start = clock.now();
100	    while (!toPrefill.isEmpty() && !isGcDetected(start)) {
101	      PreFillType toAllocate = toPrefill.remove();
102	      final Bitmap bitmap;
103	      if (!seenTypes.contains(toAllocate)) {
104	        seenTypes.add(toAllocate);
105	        bitmap =
106	            bitmapPool.getDirty(
107	                toAllocate.getWidth(), toAllocate.getHeight(), toAllocate.getConfig());
108	      } else {
109	        bitmap =
110	            Bitmap.createBitmap(
111	                toAllocate.getWidth(), toAllocate.getHeight(), toAllocate.getConfig());
112	      }
113	
114	      // Order matters here! If the Bitmap is too large or the BitmapPool is too full, it may be
115	      // recycled after the call to bitmapPool#put below.
116	      int bitmapSize = Util.getBitmapByteSize(bitmap);
117	
118	      // Don't over fill the memory cache to avoid evicting useful resources, but make sure it's
119	      // not empty so that we use all available space.
120	      if (getFreeMemoryCacheBytes() >= bitmapSize) {
121	        // We could probably make UniqueKey just always return false from equals,
122	        // but the allocation of the Key is not nearly as expensive as the allocation of the Bitmap,
123	        // so it's probably not worth it.
124	        @SuppressWarnings("PMD.AvoidInstantiatingObjectsInLoops")
125	        Key uniqueKey = new UniqueKey();
126	        memoryCache.put(uniqueKey, BitmapResource.obtain(bitmap, bitmapPool));
127	      } else {
128	        bitmapPool.put(bitmap);
129	      }
130	
131	      if (Log.isLoggable(TAG, Log.DEBUG)) {
132	        Log.d(
133	            TAG,
134	            "allocated ["
135	                + toAllocate.getWidth()
136	                + "x"
137	                + toAllocate.getHeight()
138	                + "] "
139	                + toAllocate.getConfig()
140	                + " size: "
141	                + bitmapSize);
142	      }
143	    }
144	
145	    return !isCancelled && !toPrefill.isEmpty();
146	  }
147	
148	  private boolean isGcDetected(long startTimeMs) {
149	    return clock.now() - startTimeMs >= MAX_DURATION_MS;
150	  }
151	
152	  private long getFreeMemoryCacheBytes() {
153	    return memoryCache.getMaxSize() - memoryCache.getCurrentSize();
154	  }
155	
156	  @Override
157	  public void run() {
158	    if (allocate()) {
159	      handler.postDelayed(this, getNextDelay());
160	    }
161	  }
162	
163	  private long getNextDelay() {
164	    long result = currentDelay;
165	    currentDelay = Math.min(currentDelay * BACKOFF_RATIO, MAX_BACKOFF_MS);
166	    return result;
167	  }
168	
169	  private static final class UniqueKey implements Key {
170	
171	    @Synthetic
172	    @SuppressWarnings("WeakerAccess")
173	    UniqueKey() {}
174	
175	    @Override
176	    public void updateDiskCacheKey(@NonNull MessageDigest messageDigest) {
177	      throw new UnsupportedOperationException();
178	    }
179	  }
180	
181	  @VisibleForTesting
182	  static class Clock {
183	    long now() {
184	      return SystemClock.currentThreadTimeMillis();
185	    }
186	  }
187	}
