12	import com.bumptech.glide.load.engine.cache.DiskCache;
13	import com.bumptech.glide.load.model.ModelLoader;
14	import com.bumptech.glide.load.model.ModelLoader.LoadData;
15	import com.bumptech.glide.util.LogTime;
16	import com.bumptech.glide.util.Synthetic;
17	import java.io.IOException;
18	import java.util.Collections;
