20	/**
21	 * Generates {@link com.bumptech.glide.load.data.DataFetcher DataFetchers} from original source data
22	 * using registered {@link com.bumptech.glide.load.model.ModelLoader ModelLoaders} and the model
23	 * provided for the load.
24	 *
25	 * <p>Depending on the disk cache strategy, source data may first be written to disk and then loaded
26	 * from the cache file rather than returned directly.
27	 *
28	 * <p>This object may be used by multiple threads, but only one at a time. It is not safe to access
29	 * this object on multiple threads concurrently.
30	 */
31	class SourceGenerator implements DataFetcherGenerator, DataFetcherGenerator.FetcherReadyCallback {
32	  private static final String TAG = "SourceGenerator";
33	
34	  private final DecodeHelper<?> helper;
35	  private final FetcherReadyCallback cb;
36	
37	  private volatile int loadDataListIndex;
38	  private volatile DataCacheGenerator sourceCacheGenerator;
39	  private volatile Object dataToCache;
40	  private volatile ModelLoader.LoadData<?> loadData;
41	  private volatile DataCacheKey originalKey;
42	
43	  SourceGenerator(DecodeHelper<?> helper, FetcherReadyCallback cb) {
44	    this.helper = helper;
45	    this.cb = cb;
46	  }
47	
48	  // Concurrent access isn't supported.
49	  @SuppressWarnings({"NonAtomicOperationOnVolatileField", "NonAtomicVolatileUpdate"})
50	  @Override
51	  public boolean startNext() {
52	    if (dataToCache != null) {
53	      Object data = dataToCache;
54	      dataToCache = null;
55	      try {
56	        boolean isDataInCache = cacheData(data);
57	        // If we failed to write the data to cache, the cacheData method will try to decode the
58	        // original data directly instead of going through the disk cache. Since cacheData has
59	        // already called our callback at this point, there's nothing more to do but return.
60	        if (!isDataInCache) {
61	          return true;
62	        }
63	        // If we were able to write the data to cache successfully, we now need to proceed to call
64	        // the sourceCacheGenerator below to load the data from cache.
65	      } catch (IOException e) {
66	        // An IOException means we weren't able to write data to cache or we weren't able to rewind
67	        // it after a disk cache write failed. In either case we can just move on and try the next
68	        // fetch below.
69	        if (Log.isLoggable(TAG, Log.DEBUG)) {
70	          Log.d(TAG, "Failed to properly rewind or write data to cache", e);
71	        }
72	      }
73	    }
74	
75	    if (sourceCacheGenerator != null && sourceCacheGenerator.startNext()) {
76	      return true;
77	    }
78	    sourceCacheGenerator = null;
79	
80	    loadData = null;
81	    boolean started = false;
82	    while (!started && hasNextModelLoader()) {
83	      loadData = helper.getLoadData().get(loadDataListIndex++);
84	      if (loadData != null
85	          && (helper.getDiskCacheStrategy().isDataCacheable(loadData.fetcher.getDataSource())
86	              || helper.hasLoadPath(loadData.fetcher.getDataClass()))) {
87	        started = true;
88	        startNextLoad(loadData);
89	      }
90	    }
91	    return started;
92	  }
93	
94	  private void startNextLoad(final LoadData<?> toStart) {
95	    loadData.fetcher.loadData(
96	        helper.getPriority(),
97	        new DataCallback<Object>() {
98	          @Override
99	          public void onDataReady(@Nullable Object data) {
100	            if (isCurrentRequest(toStart)) {
101	              onDataReadyInternal(toStart, data);
102	            }
103	          }
104	
105	          @Override
106	          public void onLoadFailed(@NonNull Exception e) {
107	            if (isCurrentRequest(toStart)) {
108	              onLoadFailedInternal(toStart, e);
109	            }
110	          }
111	        });
112	  }
113	
114	  // We want reference equality explicitly to make sure we ignore results from old requests.
115	  @SuppressWarnings({"PMD.CompareObjectsWithEquals", "WeakerAccess"})
116	  @Synthetic
117	  boolean isCurrentRequest(LoadData<?> requestLoadData) {
118	    LoadData<?> currentLoadData = loadData;
119	    return currentLoadData != null && currentLoadData == requestLoadData;
120	  }
121	
122	  private boolean hasNextModelLoader() {
123	    return loadDataListIndex < helper.getLoadData().size();
124	  }
125	
126	  /**
127	   * Returns {@code true} if we were able to cache the data and should try to decode the data
128	   * directly from cache and {@code false} if we were unable to cache the data and should make an
129	   * attempt to decode from source.
130	   */
131	  private boolean cacheData(Object dataToCache) throws IOException {
132	    long startTime = LogTime.getLogTime();
133	    boolean isLoadingFromSourceData = false;
134	    try {
135	      DataRewinder<Object> rewinder = helper.getRewinder(dataToCache);
136	      Object data = rewinder.rewindAndGet();
137	      Encoder<Object> encoder = helper.getSourceEncoder(data);
138	      DataCacheWriter<Object> writer = new DataCacheWriter<>(encoder, data, helper.getOptions());
139	      DataCacheKey newOriginalKey = new DataCacheKey(loadData.sourceKey, helper.getSignature());
140	      DiskCache diskCache = helper.getDiskCache();
141	      diskCache.put(newOriginalKey, writer);
142	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
143	        Log.v(
144	            TAG,
145	            "Finished encoding source to cache"
146	                + ", key: "
147	                + newOriginalKey
148	                + ", data: "
149	                + dataToCache
150	                + ", encoder: "
151	                + encoder
152	                + ", duration: "
153	                + LogTime.getElapsedMillis(startTime));
154	      }
155	
156	      if (diskCache.get(newOriginalKey) != null) {
157	        originalKey = newOriginalKey;
158	        sourceCacheGenerator =
159	            new DataCacheGenerator(Collections.singletonList(loadData.sourceKey), helper, this);
160	        // We were able to write the data to cache.
161	        return true;
162	      } else {
163	        if (Log.isLoggable(TAG, Log.DEBUG)) {
164	          Log.d(
165	              TAG,
166	              "Attempt to write: "
167	                  + originalKey
168	                  + ", data: "
169	                  + dataToCache
170	                  + " to the disk"
171	                  + " cache failed, maybe the disk cache is disabled?"
172	                  + " Trying to decode the data directly...");
173	        }
174	
175	        isLoadingFromSourceData = true;
176	        cb.onDataFetcherReady(
177	            loadData.sourceKey,
178	            rewinder.rewindAndGet(),
179	            loadData.fetcher,
180	            loadData.fetcher.getDataSource(),
181	            loadData.sourceKey);
182	      }
183	      // We failed to write the data to cache.
184	      return false;
185	    } finally {
186	      if (!isLoadingFromSourceData) {
187	        loadData.fetcher.cleanup();
188	      }
189	    }
190	  }
191	
192	  @Override
193	  public void cancel() {
194	    LoadData<?> local = loadData;
195	    if (local != null) {
196	      local.fetcher.cancel();
197	    }
198	  }
199	
200	  @SuppressWarnings("WeakerAccess")
201	  @Synthetic
202	  void onDataReadyInternal(LoadData<?> loadData, Object data) {
203	    DiskCacheStrategy diskCacheStrategy = helper.getDiskCacheStrategy();
204	    if (data != null && diskCacheStrategy.isDataCacheable(loadData.fetcher.getDataSource())) {
205	      dataToCache = data;
206	      // We might be being called back on someone else's thread. Before doing anything, we should
207	      // reschedule to get back onto Glide's thread. Then once we're back on Glide's thread, we'll
208	      // get called again and we can write the retrieved data to cache.
209	      cb.reschedule();
210	    } else {
211	      cb.onDataFetcherReady(
212	          loadData.sourceKey,
213	          data,
214	          loadData.fetcher,
215	          loadData.fetcher.getDataSource(),
216	          originalKey);
217	    }
218	  }
219	
220	  @SuppressWarnings("WeakerAccess")
221	  @Synthetic
222	  void onLoadFailedInternal(LoadData<?> loadData, @NonNull Exception e) {
223	    cb.onDataFetcherFailed(originalKey, e, loadData.fetcher, loadData.fetcher.getDataSource());
224	  }
225	
226	  @Override
227	  public void reschedule() {
228	    // We don't expect this to happen, although if we ever need it to we can delegate to our
229	    // callback.
230	    throw new UnsupportedOperationException();
231	  }
232	
233	  // Called from source cache generator.
234	  @Override
235	  public void onDataFetcherReady(
236	      Key sourceKey, Object data, DataFetcher<?> fetcher, DataSource dataSource, Key attemptedKey) {
237	    // This data fetcher will be loading from a File and provide the wrong data source, so override
238	    // with the data source of the original fetcher
239	    cb.onDataFetcherReady(sourceKey, data, fetcher, loadData.fetcher.getDataSource(), sourceKey);
240	  }
241	
242	  @Override
243	  public void onDataFetcherFailed(
244	      Key sourceKey, Exception e, DataFetcher<?> fetcher, DataSource dataSource) {
245	    cb.onDataFetcherFailed(sourceKey, e, fetcher, loadData.fetcher.getDataSource());
246	  }
247	}
