2	
3	import com.bumptech.glide.util.Preconditions;
4	import com.bumptech.glide.util.Synthetic;
5	import java.util.ArrayDeque;
6	import java.util.HashMap;
7	import java.util.Map;
8	import java.util.Queue;
9	import java.util.concurrent.locks.Lock;
10	import java.util.concurrent.locks.ReentrantLock;
11	
12	/**
13	 * Keeps a map of keys to locks that allows locks to be removed from the map when no longer in use
14	 * so the size of the collection is bounded.
15	 *
16	 * <p>This class will be accessed by multiple threads in a thread pool and ensures that the number
17	 * of threads interested in each lock is updated atomically so that when the count reaches 0, the
18	 * lock can safely be removed from the map.
19	 */
20	final class DiskCacheWriteLocker {
21	  private final Map<String, WriteLock> locks = new HashMap<>();
22	  private final WriteLockPool writeLockPool = new WriteLockPool();
23	
24	  void acquire(String safeKey) {
25	    WriteLock writeLock;
26	    synchronized (this) {
27	      writeLock = locks.get(safeKey);
28	      if (writeLock == null) {
29	        writeLock = writeLockPool.obtain();
30	        locks.put(safeKey, writeLock);
31	      }
32	      writeLock.interestedThreads++;
33	    }
34	
35	    writeLock.lock.lock();
36	  }
37	
38	  void release(String safeKey) {
39	    WriteLock writeLock;
40	    synchronized (this) {
41	      writeLock = Preconditions.checkNotNull(locks.get(safeKey));
42	      if (writeLock.interestedThreads < 1) {
43	        throw new IllegalStateException(
44	            "Cannot release a lock that is not held"
45	                + ", safeKey: "
46	                + safeKey
47	                + ", interestedThreads: "
48	                + writeLock.interestedThreads);
49	      }
50	
51	      writeLock.interestedThreads--;
52	      if (writeLock.interestedThreads == 0) {
53	        WriteLock removed = locks.remove(safeKey);
54	        if (!removed.equals(writeLock)) {
55	          throw new IllegalStateException(
56	              "Removed the wrong lock"
57	                  + ", expected to remove: "
58	                  + writeLock
59	                  + ", but actually removed: "
60	                  + removed
61	                  + ", safeKey: "
62	                  + safeKey);
63	        }
64	        writeLockPool.offer(removed);
65	      }
66	    }
67	
68	    writeLock.lock.unlock();
69	  }
70	
71	  private static class WriteLock {
72	    final Lock lock = new ReentrantLock();
73	    int interestedThreads;
74	
75	    @Synthetic
76	    WriteLock() {}
77	  }
78	
79	  private static class WriteLockPool {
80	    private static final int MAX_POOL_SIZE = 10;
81	    private final Queue<WriteLock> pool = new ArrayDeque<>();
82	
83	    @Synthetic
84	    WriteLockPool() {}
85	
86	    WriteLock obtain() {
87	      WriteLock result;
88	      synchronized (pool) {
89	        result = pool.poll();
90	      }
91	      if (result == null) {
92	        result = new WriteLock();
93	      }
94	      return result;
95	    }
96	
97	    void offer(WriteLock writeLock) {
98	      synchronized (pool) {
99	        if (pool.size() < MAX_POOL_SIZE) {
100	          pool.offer(writeLock);
101	        }
102	      }
103	    }
104	  }
105	}
