2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Map;
6	
7	final class PreFillQueue {
8	
9	  private final Map<PreFillType, Integer> bitmapsPerType;
10	  private final List<PreFillType> keyList;
11	  private int bitmapsRemaining;
12	  private int keyIndex;
13	
14	  public PreFillQueue(Map<PreFillType, Integer> bitmapsPerType) {
15	    this.bitmapsPerType = bitmapsPerType;
16	    // We don't particularly care about the initial order.
17	    keyList = new ArrayList<>(bitmapsPerType.keySet());
18	
19	    for (Integer count : bitmapsPerType.values()) {
20	      bitmapsRemaining += count;
21	    }
22	  }
23	
24	  public PreFillType remove() {
25	    PreFillType result = keyList.get(keyIndex);
26	
27	    Integer countForResult = bitmapsPerType.get(result);
28	    if (countForResult == 1) {
29	      bitmapsPerType.remove(result);
30	      keyList.remove(keyIndex);
31	    } else {
32	      bitmapsPerType.put(result, countForResult - 1);
33	    }
34	    bitmapsRemaining--;
35	
36	    // Avoid divide by 0.
37	    keyIndex = keyList.isEmpty() ? 0 : (keyIndex + 1) % keyList.size();
38	
39	    return result;
40	  }
41	
42	  public int getSize() {
43	    return bitmapsRemaining;
44	  }
45	
46	  public boolean isEmpty() {
47	    return bitmapsRemaining == 0;
48	  }
49	}
