15	 * recycle the resource.
16	 */
17	final class LockedResource<Z> implements Resource<Z>, FactoryPools.Poolable {
18	  private static final Pools.Pool<LockedResource<?>> POOL =
19	      FactoryPools.threadSafe(
20	          20,
21	          new FactoryPools.Factory<LockedResource<?>>() {
22	            @Override
23	            public LockedResource<?> create() {
24	              return new LockedResource<Object>();
25	            }
26	          });
27	  private final StateVerifier stateVerifier = StateVerifier.newInstance();
28	  private Resource<Z> toWrap;
29	  private boolean isLocked;
30	  private boolean isRecycled;
31	
32	  @SuppressWarnings("unchecked")
33	  @NonNull
34	  static <Z> LockedResource<Z> obtain(Resource<Z> resource) {
35	    LockedResource<Z> result = Preconditions.checkNotNull((LockedResource<Z>) POOL.acquire());
36	    result.init(resource);
