40	  @SuppressWarnings("WeakerAccess")
41	  @Synthetic
42	  LockedResource() {}
43	
44	  private void init(Resource<Z> toWrap) {
45	    isRecycled = false;
46	    isLocked = true;
47	    this.toWrap = toWrap;
48	  }
49	
50	  private void release() {
51	    toWrap = null;
52	    POOL.release(this);
53	  }
