67	  @NonNull
68	  @Override
69	  public Class<Z> getResourceClass() {
70	    return toWrap.getResourceClass();
71	  }
72	
73	  @NonNull
74	  @Override
75	  public Z get() {
76	    return toWrap.get();
77	  }
78	
79	  @Override
80	  public int getSize() {
81	    return toWrap.getSize();
82	  }
83	
84	  @Override
85	  public synchronized void recycle() {
86	    stateVerifier.throwIfRecycled();
87	
88	    this.isRecycled = true;
89	    if (!isLocked) {
90	      toWrap.recycle();
91	      release();
92	    }
93	  }
94	
95	  @NonNull
96	  @Override
97	  public StateVerifier getVerifier() {
