3	import android.os.Handler;
4	import android.os.Looper;
5	import android.os.Message;
6	import com.bumptech.glide.util.Synthetic;
7	
8	/** A class that can safely recycle recursive resources. */
9	class ResourceRecycler {
10	  private boolean isRecycling;
11	  private final Handler handler =
12	      new Handler(Looper.getMainLooper(), new ResourceRecyclerCallback());
13	
14	  synchronized void recycle(Resource<?> resource, boolean forceNextFrame) {
15	    if (isRecycling || forceNextFrame) {
16	      // If a resource has sub-resources, releasing a sub resource can cause it's parent to be
17	      // synchronously evicted which leads to a recycle loop when the parent releases it's children.
18	      // Posting breaks this loop.
19	      handler.obtainMessage(ResourceRecyclerCallback.RECYCLE_RESOURCE, resource).sendToTarget();
20	    } else {
21	      isRecycling = true;
22	      resource.recycle();
23	      isRecycling = false;
24	    }
25	  }
26	
27	  private static final class ResourceRecyclerCallback implements Handler.Callback {
28	    static final int RECYCLE_RESOURCE = 1;
29	
30	    @Synthetic
31	    ResourceRecyclerCallback() {}
32	
33	    @Override
34	    public boolean handleMessage(Message message) {
35	      if (message.what == RECYCLE_RESOURCE) {
36	        Resource<?> resource = (Resource<?>) message.obj;
37	        resource.recycle();
38	        return true;
39	      }
40	      return false;
41	    }
42	  }
43	}
