2	
3	import android.graphics.Bitmap;
4	import androidx.annotation.VisibleForTesting;
5	import com.bumptech.glide.load.DecodeFormat;
6	import com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool;
7	import com.bumptech.glide.load.engine.cache.MemoryCache;
8	import com.bumptech.glide.util.Util;
9	import java.util.HashMap;
10	import java.util.Map;
11	
12	/**
13	 * A class for pre-filling {@link android.graphics.Bitmap Bitmaps} in a {@link
14	 * com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool}.
15	 */
16	public final class BitmapPreFiller {
17	
18	  private final MemoryCache memoryCache;
19	  private final BitmapPool bitmapPool;
20	  private final DecodeFormat defaultFormat;
21	
22	  private BitmapPreFillRunner current;
23	
24	  public BitmapPreFiller(
25	      MemoryCache memoryCache, BitmapPool bitmapPool, DecodeFormat defaultFormat) {
26	    this.memoryCache = memoryCache;
27	    this.bitmapPool = bitmapPool;
28	    this.defaultFormat = defaultFormat;
29	  }
30	
31	  @SuppressWarnings("deprecation")
32	  public void preFill(PreFillType.Builder... bitmapAttributeBuilders) {
33	    if (current != null) {
34	      current.cancel();
35	    }
36	
37	    PreFillType[] bitmapAttributes = new PreFillType[bitmapAttributeBuilders.length];
38	    for (int i = 0; i < bitmapAttributeBuilders.length; i++) {
39	      PreFillType.Builder builder = bitmapAttributeBuilders[i];
40	      if (builder.getConfig() == null) {
41	        builder.setConfig(
42	            defaultFormat == DecodeFormat.PREFER_ARGB_8888
43	                ? Bitmap.Config.ARGB_8888
44	                : Bitmap.Config.RGB_565);
45	      }
46	      bitmapAttributes[i] = builder.build();
47	    }
48	
49	    PreFillQueue allocationOrder = generateAllocationOrder(bitmapAttributes);
50	    current = new BitmapPreFillRunner(bitmapPool, memoryCache, allocationOrder);
51	    Util.postOnUiThread(current);
52	  }
53	
54	  @VisibleForTesting
55	  PreFillQueue generateAllocationOrder(PreFillType... preFillSizes) {
56	    final long maxSize =
57	        memoryCache.getMaxSize() - memoryCache.getCurrentSize() + bitmapPool.getMaxSize();
58	
59	    int totalWeight = 0;
60	    for (PreFillType size : preFillSizes) {
61	      totalWeight += size.getWeight();
62	    }
63	
64	    final float bytesPerWeight = maxSize / (float) totalWeight;
65	
66	    Map<PreFillType, Integer> attributeToCount = new HashMap<>();
67	    for (PreFillType size : preFillSizes) {
68	      int bytesForSize = Math.round(bytesPerWeight * size.getWeight());
69	      int bytesPerBitmap = getSizeInBytes(size);
70	      int bitmapsForSize = bytesForSize / bytesPerBitmap;
71	      attributeToCount.put(size, bitmapsForSize);
72	    }
73	
74	    return new PreFillQueue(attributeToCount);
75	  }
76	
77	  private static int getSizeInBytes(PreFillType size) {
78	    return Util.getBitmapByteSize(size.getWidth(), size.getHeight(), size.getConfig());
79	  }
80	}
